-- ============================================================
-- BrainDev Importacion de gastos historicos (AppSheet)
-- Archivo 1 de 4 — filas 1 a 8000 (8000)
-- Pre-requisitos: (1) ejecutar los archivos en orden 1 -> 4.
--   (2) el archivo parte 1 crea los departamentos si no existen.
--   (3) debe existir al menos un perfil (el importador usa el id de un
--       perfil, prefiriendo uno admin, como registrado_por).
--   (4) cada archivo corre dentro de una transaccion (begin/commit).
-- ============================================================

begin;

