) as v(dep, concepto, numero_factura, fecha, moneda, monto, tasa, created_at)
join public.departamentos d on d.nombre = v.dep
cross join (
  select coalesce(
    (select id from public.profiles where role = 'admin' order by created_at limit 1),
    (select id from public.profiles order by created_at limit 1)
  ) as id
) a;

insert into public.movimientos
  (tipo, departamento_id, concepto, numero_factura, fecha, moneda, monto, tasa_cambio, registrado_por, created_at)
